   160| * Hook result for useUpdateStatus — provides update state to the UI.
   161| */
   162|export interface UpdateStatusState {
   163|  isChecking: boolean;
   164|  hasUpdate: boolean;
   165|  error: string | null;
   166|  diagnostics: UpdateDiagnostics | null;
   167|  lastCheckedAt: string | null;
