   170|/**
   171| * React hook that provides non-fatal update status.
   172| * Call this in a top-level component to enable background update checking.
   173| * The hook NEVER throws and NEVER blocks app rendering.
   174| */
   175|export function useUpdateStatus(): UpdateStatusState & { checkNow: () => Promise<void> } {
   176|  // This is a minimal hook that doesn't use React state to avoid
