   179|
   180|  return {
   181|    isChecking: false,
   182|    hasUpdate: false,
   183|    error: null,
   184|    diagnostics: null,
   185|    lastCheckedAt: null,
   186|    checkNow: async () => {
   187|      try {
   188|        await safelyCheckForUpdates();
   189|      } catch {
   190|        // Never let this propagate
   191|      }
   192|    },
   193|  };
